css:
 @page { size:A4; margin: 8mm 8mm 10mm 8mm; }
 body { font-family: Arial, sans-serif; font-size: 11px; color:#111; margin:0; }
 .ar { direction:rtl; text-align:right; }
 .muted { color:#555; font-size:10px; }
 .header-section{
 display:flex;
 justify-content:space-between;
 align-items:center;
 border-bottom:1px solid #eee;
 padding-bottom:6px;
 margin-bottom:8px;
}
.logo-container{ width:85px; }
.logo{ max-width:80px; max-height:45px; object-fit:contain; display:block; }
.company-names{ flex:1; text-align:center; line-height:1.1; }
.company-names .en{ font-weight:900; margin:0; font-size:12px; text-align:center; }
.company-names .ar{ font-weight:900; margin:2px 0 0 0; font-size:13px; direction:rtl; text-align:center; }

 /* hide default frappe headings if they appear */
 .print-heading, .print-format-meta, .visible-xs { display:none !important; }

 /* ===== HEADER TABLE (3 rows, 2 cols) ===== */
 .hdr-tbl { width:100%; border-collapse:collapse; margin-bottom:8px; }
 .hdr-tbl td { padding:2px 4px; vertical-align:middle; }
 .hdr-sep { border-bottom:1px solid #eee; padding-bottom:6px; }

 .logo-cell { width:80px; }
 .logo-cell img { max-width:78px; max-height:44px; object-fit:contain; display:block; }
 
.co-en { font-weight:900; font-size:12px; text-align:center; }
.co-ar { font-weight:900; font-size:13px; text-align:center; }

 .h-en { font-weight:900; font-size:12.5px; text-align:left; padding-top:4px; }
 .h-ar { font-weight:900; font-size:13.5px; padding-top:4px; }

 /* ===== META LINE (CENTER + CLEAN) ===== */
 .meta-line{
 width:100%;
 display:flex; justify-content:center; align-items:center;
 gap:18px; flex-wrap:wrap;
 padding: 6px 0 8px 0;
 border-bottom:1px solid #f0f0f0;
 margin-bottom:10px;
 }
 .meta-it{ display:flex; gap:6px; align-items:baseline; }
 .meta-k{ font-weight:900; }
 .meta-v{ font-weight:700; color:#222; }

 /* ===== SECTION TITLES ===== */
 .sec-title{
 margin: 10px 0 5px 0;
 display:flex; justify-content:space-between; align-items:baseline;
 font-weight:900;
 }
 .sec-title .en{ text-align:left; }
 .sec-title .ar{ }

 /* ===== TABLE ===== */
 table.chk-tbl { width:100%; border-collapse:collapse; table-layout:fixed; }
 table.chk-tbl th{
 font-weight:900; font-size:10.5px; color:#333;
 border-bottom:1px solid #eaeaea;
 padding: 2px 5px;
 }
 table.chk-tbl td{
 border-bottom:1px solid #f1f1f1;
 padding: 5px 6px;
 line-height: 1.02 !important; /* was 1.2+ */
 vertical-align:top;
 word-wrap:break-word;
 }
 table.chk-tbl tr:last-child td{ border-bottom:0; }

 .item { width:58%; }
 .chk { width:8%; text-align:center; font-weight:900; }
 .notes { width:26%; }

 /* ===== SIGNATURES ===== */
 .signs{ margin-top:14px; display:flex; gap:14px; }
 .sign{ flex:1; min-height:120px; position:relative; }
 .sign .h{ font-weight:900; display:flex; justify-content:space-between; }
 .sign img{ max-height:42px; margin-top:8px; display:block; }
 .sign .line{ position:absolute; left:0; right:0; bottom:34px; border-top:1px solid #999; }
 .sign .name{ position:absolute; left:0; bottom:10px; font-size:10px; font-weight:800; color:#333; }

 /* ===== FOOTER ===== */
 .ftr{
 margin-top:12px;
 padding-top:6px;
 border-top:1px solid #eee;
 font-size:10px;
 color:#333;
 display:flex; justify-content:space-between; gap:10px;
 }

html:
{# --- Staff and Company resolve (based on your Staff field: company_name) --- #}
{% set staff_name = doc.staff or doc.driver or doc.employee or "" %}

{# staff_company_name MUST be the Company docname #}
{% set staff_company_name =
 doc.company
 or (frappe.db.get_value("Staff", staff_name, "company_name") if staff_name else "")
 or ""
%}

{# --- Company meta (use staff_company_name) --- #}
{% set company_logo = frappe.db.get_value("Company", staff_company_name, "company_logo") or "" %}
{% set company_en = frappe.db.get_value("Company", staff_company_name, "company_name") or "" %}
{% set company_ar = frappe.db.get_value("Company", staff_company_name, "company_name_arabic") or "" %}
{% set phone_no = frappe.db.get_value("Company", staff_company_name, "phone_no") or "" %}
{% set reg_no = frappe.db.get_value("Company", staff_company_name, "registration_details") or "" %}
{# --- helper ticks --- #}
{% macro tick(is_on) -%}{% if is_on %}✓{% else %}&nbsp;{% endif %}{%- endmacro %}
{% macro yn_cols(status) -%}
 {% set st = (status or "") %}
 <td class="chk">{{ tick("Unsound" not in st) }}</td>
 <td class="chk">{{ tick("Unsound" in st) }}</td>
{%- endmacro %}

{# ===================== HEADER (ONLY THIS) ===================== #}
<header class="header-section">
 <div class="logo-container">
 {% if company_logo %}
 <img class="logo" src="{{ company_logo }}" alt="Company Logo">
 {% endif %}
 </div>

 <div class="company-names">
 <p class="en">{{ company_en }}</p>
 <p class="ar">{{ company_ar }}</p>
 </div>
</header>

{# ===================== META LINE (CENTERED) ===================== #}
<div class="meta-line">
 {% if doc.inspection_date %}
 <div class="meta-it">
 <span class="meta-k">Date</span>
 <span class="meta-v">{{ doc.inspection_date }}</span>
 <span class="meta-k ar">التاريخ</span>
 </div>
 {% endif %}

 {% if doc.driver %}
 <div class="meta-it">
 <span class="meta-k">Driver</span>
 <span class="meta-v">{{ doc.driver }}</span>
 <span class="meta-k ar">السائق</span>
 </div>
 {% endif %}

 {% if doc.vehicle %}
 <div class="meta-it">
 <span class="meta-k">Vehicle</span>
 <span class="meta-v">{{ doc.vehicle }}</span>
 <span class="meta-k ar">المركبة</span>
 </div>
 {% endif %}
</div>

{# ===================== GROUP ITEMS BY SECTION ===================== #}
{% set groups = {} %}
{% for r in (doc.items or []) %}
 {% set sec = (r.section or r.category or "Checklist") %}
 {% if sec not in groups %}{% set _ = groups.update({sec: []}) %}{% endif %}
 {% set _ = groups[sec].append(r) %}
{% endfor %}

{# ===================== SECTIONS ===================== #}
{% for sec, rows in groups.items() %}
 {% if rows and rows|length > 0 %}

 {% if "Dashboard" in sec or "Indicators" in sec %}
 {% set sec_ar = "مؤشرات لوحة القيادة" %}
 {% set sec_en = "Indicators Dashboard" %}
 {% elif "External" in sec %}
 {% set sec_ar = "فحص الأجزاء الخارجية" %}
 {% set sec_en = "Inspection External" %}
 {% elif "Safety" in sec or "Security" in sec %}
 {% set sec_ar = "أدوات ومتطلبات السلامة" %}
 {% set sec_en = "Tools Security & Safety" %}
 {% else %}
 {% set sec_ar = "" %}
 {% set sec_en = sec %}
 {% endif %}

 <div class="sec-title">
 <div class="ar">{{ sec_ar }}</div>
 <div class="en">{{ sec_en }}</div>
 </div>

 <table class="chk-tbl">
 <thead>
 <tr>
 <th class="item">Item | <span class="ar">البند</span></th>
 <th class="chk">Sound<br><span class="ar">سليم</span></th>
 <th class="chk">Unsound<br><span class="ar">غير سليم</span></th>
 <th class="notes">Notes<br><span class="ar">ملاحظات</span></th>
 </tr>
 </thead>
 <tbody>
 {% for r in rows %}
 <tr>
 <td class="item">{{ r.item or "" }}</td>
 {{ yn_cols(r.status) }}
 <td class="notes">{{ r.notes or "" }}</td>
 </tr>
 {% endfor %}
 </tbody>
 </table>

 {% endif %}
{% endfor %}

{# ===================== SIGNATURES ===================== #}
<div class="signs">
 <div class="sign">
 <div class="h">
 <div class="ar">توقيع السائق</div>
 <div>Driver Signature</div>
 </div>
 {% if doc.driver_signature %}
 <img src="{{ doc.driver_signature | abs_url }}">
 {% endif %}
 <div class="line"></div>
 <div class="name">Name: {{ doc.driver_name_text or doc.driver or "" }}</div>
 </div>

 <div class="sign">
 <div class="h">
 <div class="ar">توقيع المشرف</div>
 <div>Supervisor Signature</div>
 </div>
 {% if doc.supervisor_signature %}
 <img src="{{ doc.supervisor_signature }}">
 {% endif %}
 <div class="line"></div>
 <div class="name">Name: {{ doc.supervisor_name_text or "" }}</div>
 </div>
</div>

{# ===================== FOOTER ===================== #}
{% if phone_no or reg_no %}
<div class="ftr">
 <div class="ar">
 {% if phone_no %}الهاتف: {{ phone_no }}{% endif %}
 {% if phone_no and reg_no %} | {% endif %}
 {% if reg_no %}رقم التسجيل: {{ reg_no }}{% endif %}
 </div>
 <div>
 {% if phone_no %}Phone: {{ phone_no }}{% endif %}
 {% if phone_no and reg_no %} | {% endif %}
 {% if reg_no %}Reg: {{ reg_no }}{% endif %}
 </div>
</div>
{% endif %}
